	for _, track in ipairs(EmbeddedTracks) do
		local path = "UhhhhhhReanim/Assets/" .. track[1]
		local s, e = pcall(function()
			if not isfile(path) or #readfile(path) ~= track[2] then
				writefile(path, DecodeBase64(track[3]))
			end
		end)
		if not s then
			Util.Notify("Failed to write embedded track " .. track[1] .. ": " .. tostring(e))
		end
		track[3] = nil
	end
end
do
	local BuiltinTracks = {
		{"shootingstars_embedded.mp3", "Shooting Stars"},
		{"nevergonnagiveyouup_embedded.mp3", "Never Gonna Give You Up"},
		{"driftveilcity_embedded.mp3", "Driftveil City"},
	}
	local function FileExists(path)
		local s, d = pcall(isfile, path)
		return s and d and true or false
	end
	for _, track in ipairs(BuiltinTracks) do
		local path = "UhhhhhhReanim/Assets/" .. track[1]
		if FileExists(path) then
			table.insert(MusicPlayer.Database, {path, track[2]})
		end
	end
	-- your own songs: drop .mp3 / .ogg files into UhhhhhhReanim/Muzik/
	local s, files = pcall(listfiles, "UhhhhhhReanim/Muzik")
	if s and type(files) == "table" then
		local names = {}
		for _, f in ipairs(files) do
			-- some executors return full / backslash paths, so only keep the file name
			local fname = tostring(f):gsub("\\", "/"):match("([^/]+)$")
			if fname and fname:lower():match("%.mp3$") or fname and fname:lower():match("%.ogg$") then
				table.insert(names, fname)
			end
		end
		table.sort(names)
		for _, fname in ipairs(names) do
			local path = "UhhhhhhReanim/Muzik/" .. fname
			if FileExists(path) then
				local title = fname:gsub("%.[^%.]+$", ""):gsub("_", " ")
				table.insert(MusicPlayer.Database, {path, title})
			end
		end
	end
	if #MusicPlayer.Database == 0 then
		Util.Notify("No UI music found. Make sure your executor can write files, or put .mp3 files in UhhhhhhReanim/Muzik/")
	end
end
UISound.Music.Name = "None"
MusicPlayer.Switching = false
MusicPlayer.Last = 1
MusicPlayer.PlayMusic = function(i)
	if #MusicPlayer.Database == 0 then return end
	if MusicPlayer.Switching then return end
	MusicPlayer.Switching = true
	local last = MusicPlayer.LastMusic
	if not i then
		i = last
		while i == last do
			i = math.random(1, #MusicPlayer.Database)
			if #MusicPlayer.Database <= 1 then break end
			task.wait()
		end
	end
	MusicPlayer.LastMusic = i
	local hi = MusicPlayer.Database[i]
	local soundid, soundname = hi[1], hi[2]
	local s, id = pcall(isfile, soundid)
	if s and id then
		s, id = pcall(getcustomasset, soundid)
		if s then
			soundid = id
		else
			soundid = ""
		end
	else
		soundid = ""
	end
	if #soundid == 0 then
		MusicPlayer.Switching = false
		MusicPlayer.Failures = (MusicPlayer.Failures or 0) + 1
		if MusicPlayer.Failures > #MusicPlayer.Database * 2 then
			MusicPlayer.Failures = 0
			return
		end
		return MusicPlayer.PlayMusic()
	end
	MusicPlayer.Failures = 0
	UISound.Music.SoundId = soundid
	UISound.Music.Name = soundname
	UISound.Music:Stop()
	task.wait()
	UISound.Music.TimePosition = 0
	task.wait()
	UISound.Music:Play()
	task.wait()
	MusicPlayer.Switching = false
end
UISound.Music.Ended:Connect(function()
	MusicPlayer.PlayMusic()
end)

