		local RB_SEG = 4 -- width of one rainbow step (sprite pixels)
		local RB_THICK = 3 -- thickness of one colour stripe (sprite pixels)

		-- draws a layer of the sprite from its text rows (merges equal pixels into big rectangles)
		local function buildlayer(parent, rows, ox, oy, z)
			local holder = new("Frame", parent, {
				Position = UDim2.fromOffset(ox * P, oy * P),
				Size = UDim2.fromOffset(#rows[1] * P, #rows * P),
				BackgroundTransparency = 1,
				BorderSizePixel = 0,
				ZIndex = z,
			})
			local rects = {}
			local active = {}
			for y, row in ipairs(rows) do
				local nextactive = {}
				local x = 1
				while x <= #row do
					local ch = string.sub(row, x, x)
					local x2 = x
					while string.sub(row, x2 + 1, x2 + 1) == ch do
						x2 += 1
					end
					if CAT_COLORS[ch] then
						local key = x .. ":" .. x2 .. ":" .. ch
						local r = active[key]
						if r then
							r.h += 1
						else
							r = {x = x, x2 = x2, y = y, h = 1, ch = ch}
							rects[#rects + 1] = r
						end
						nextactive[key] = r
					end
					x = x2 + 1
				end
				active = nextactive
			end
			for _, r in rects do
				new("Frame", holder, {
					Position = UDim2.fromOffset((r.x - 1) * P, (r.y - 1) * P),
					Size = UDim2.fromOffset((r.x2 - r.x + 1) * P, r.h * P),
					BackgroundColor3 = CAT_COLORS[r.ch],
					BorderSizePixel = 0,
					ZIndex = z,
				})
			end
			return holder
		end

		local space = new("Frame", scene, {
			Size = UDim2.new(1, 0, 1, 0),
			BackgroundColor3 = WHITE,
			BorderSizePixel = 0,
			ClipsDescendants = true,
			ZIndex = 3,
		})
		new("UIGradient", space, {
			Rotation = 90,
			Color = ColorSequence.new(Color3.fromRGB(0, 51, 102), Color3.fromRGB(0, 51, 102)),
		})
		local nyanstars = {}
		-- sparkle arm length per twinkle step (-1 = hidden); stars twinkle in 6 steps like the original
		local STAR_STEPS_BIG = {0, 1, 2, 1, 0, -1}
		local STAR_STEPS_SMALL = {-1, 0, 1, 0, -1, -1}
		local GRID_W = math.ceil(W / P) + 8
		local GRID_H = math.ceil(H / P)
		local function mkstar()
			return new("Frame", space, {
				AnchorPoint = Vector2.new(0.5, 0.5),
				Size = UDim2.fromOffset(P, P),
				BackgroundColor3 = WHITE,
				BorderSizePixel = 0,
				ZIndex = 4,
			})
		end
		for i = 1, math.clamp(math.floor(GRID_W * GRID_H / 170), 16, 56) do
			nyanstars[i] = {
				f = mkstar(),
				v = mkstar(),
				big = rng:NextInteger(1, 3) == 1,
				gx = rng:NextInteger(0, GRID_W - 1),
				gy = rng:NextInteger(1, math.max(2, GRID_H - 2)),
				ph = rng:NextInteger(0, 5),
			}
		end

		-- rainbow trail: stepped bands, each one is 6 hard colour stripes made with a UIGradient
		local rbkeys = {}
		for i, c in ipairs(RAINBOW) do
			rbkeys[#rbkeys + 1] = ColorSequenceKeypoint.new(i == 1 and 0 or (i - 1) / 6 + 0.001, c)
			rbkeys[#rbkeys + 1] = ColorSequenceKeypoint.new(i == #RAINBOW and 1 or i / 6 - 0.001, c)
		end
		local trailcw = P * RB_SEG
		local trail = {}
		for j = 1, math.ceil(W / trailcw) + 6 do
			local col = new("Frame", space, {
				Size = UDim2.fromOffset(trailcw, P * RB_THICK * #RAINBOW),
				BackgroundColor3 = WHITE,
				BorderSizePixel = 0,
				ZIndex = 8,
			})
			new("UIGradient", col, {Rotation = 90, Color = ColorSequence.new(rbkeys)})
			trail[j] = col
		end

		local cat = new("Frame", space, {
			Size = UDim2.fromOffset(CAT_W * P, CAT_H * P),
			BackgroundTransparency = 1,
			BorderSizePixel = 0,
			ZIndex = 12,
		})
		local catassets = {}
		for i = 1, 12 do
			local a = Util.GetCDNAsset("nyan" .. i .. ".png")
			if #a == 0 then break end
			catassets[#catassets + 1] = a
		end
		if #catassets == 0 then
			local single = Util.GetCDNAsset("nyan.png")
			if #single > 0 then
				catassets[1] = single
			end
		end
		local catimages = {}
		local legs, tails, bodyholder = {}, {}, nil
		if #catassets > 0 then
			-- one ImageLabel per frame (all loaded up front), the loop just shows the current one
			for i, a in ipairs(catassets) do
				catimages[i] = new("ImageLabel", cat, {
					Size = UDim2.new(1, 0, 1, 0),
					BackgroundTransparency = 1,
					BorderSizePixel = 0,
					Image = a,
					ScaleType = Enum.ScaleType.Fit,
					Visible = (i == 1),
					ZIndex = 12,
				})
			end
		else
			-- drawn sprite: legs at the back, then tail + body (they bob together)
			for i, def in ipairs(NYAN_LEGSET) do
				legs[i] = buildlayer(cat, def.rows, def.x, def.y + BODY_Y0, 12)
			end
			bodyholder = new("Frame", cat, {
				Position = UDim2.fromOffset(0, BODY_Y0 * P),
				Size = UDim2.new(1, 0, 1, 0),
				BackgroundTransparency = 1,
				BorderSizePixel = 0,
				ZIndex = 13,
			})
			for name, rows in NYAN_TAILS do
				tails[name] = buildlayer(bodyholder, rows, TAIL_X, TAIL_Y0, 13)
				tails[name].Visible = (name == "up")
			end
			buildlayer(bodyholder, NYAN_BODY, 0, 0, 14)
		end

		local sceneimg = nil
		local lastframe = 0
		if #SceneFrames > 0 then
			sceneimg = new("ImageLabel", space, {
				Size = UDim2.new(1, 0, 1, 0),
				BackgroundTransparency = 1,
				BorderSizePixel = 0,
				Image = SceneFrames[1],
				ScaleType = Enum.ScaleType.Crop,
				ZIndex = 5,
			})
			cat.Visible = false
			for _, st0 in nyanstars do
				st0.f.Visible = false
				st0.v.Visible = false
			end
			for _, c0 in trail do
				c0.Visible = false
			end
			-- load every frame in the background while the BIOS text is on screen
			task.spawn(function()
				local labels = {}
				for i, a in ipairs(SceneFrames) do
					labels[i] = new("ImageLabel", space, {
						Visible = false,
						Size = UDim2.fromOffset(1, 1),
						BackgroundTransparency = 1,
						Image = a,
					})
				end
				pcall(function()
					ContentProviderService:PreloadAsync(labels)
				end)
			end)
		end

		-- title + subtitle (shadow, chromatic split, main)
		local function mktext(txt, color, z)
			return new("TextLabel", scene, {
				AnchorPoint = Vector2.new(0.5, 0.5),
				BackgroundTransparency = 1,
				Font = Enum.Font.Arcade,
				Text = txt,
				TextColor3 = color,
				TextScaled = true,
				MaxVisibleGraphemes = 0,
				ZIndex = z,
			})
		end
		local function place(label, x, y, w, h, n)
			label.Position = UDim2.fromOffset(x, y)
			label.Size = UDim2.fromOffset(w, h)
			label.MaxVisibleGraphemes = n
		end
		local tShadow = mktext("UHHHHHH", Color3.fromRGB(20, 0, 40), 31)
		local tMag = mktext("UHHHHHH", WHITE, 32)
		local tCyan = mktext("UHHHHHH", WHITE, 33)
		local tMain = mktext("UHHHHHH", WHITE, 34)
		local gMag = new("UIGradient", tMag, {})
		local gCyan = new("UIGradient", tCyan, {})
		local gMain = new("UIGradient", tMain, {})
		local function setrainbow(grad, h0)
			local kps = {}
			for i = 0, 15 do
				local pos = i / 15
				kps[#kps + 1] = ColorSequenceKeypoint.new(pos, Color3.fromHSV((h0 + pos * 1.5) % 1, 0.85, 1))
			end
			grad.Color = ColorSequence.new(kps)
		end
		local sShadow = mktext("REANIMATE", Color3.fromRGB(20, 0, 40), 31)
		local sMain = mktext("REANIMATE", YELLOW, 32)
		local glitchtimes = {3.75, 4.35, 4.95, 5.5}
		local glitchbar = new("Frame", scene, {
			Size = UDim2.new(1, 0, 0, 8),
			BackgroundColor3 = WHITE,
			BackgroundTransparency = 0.65,
			BorderSizePixel = 0,
			Visible = false,
			ZIndex = 60,
		})

		-- loading bar
		local barframe = new("Frame", scene, {
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.new(0.5, 0, 0.9, 0),
			Size = UDim2.new(0.5, 0, 0, 16),
			BackgroundColor3 = Color3.fromRGB(10, 0, 25),
			BorderSizePixel = 2,
			BorderColor3 = CYAN,
			ZIndex = 40,
		})
		local barfill = new("Frame", barframe, {
			Size = UDim2.new(0, 0, 1, 0),
			BackgroundColor3 = WHITE,
			BorderSizePixel = 0,
			ZIndex = 41,
		})
		new("UIGradient", barfill, {Color = ColorSequence.new(CYAN, MAGENTA)})
		for i = 1, 19 do
			new("Frame", barframe, {
				Position = UDim2.new(i / 20, -1, 0, 0),
				Size = UDim2.new(0, 2, 1, 0),
				BackgroundColor3 = Color3.fromRGB(10, 0, 25),
				BorderSizePixel = 0,
				ZIndex = 42,
			})
		end
		local labelsize = math.clamp(math.floor(H / 45), 12, 24)
		local barlabel = new("TextLabel", scene, {
			AnchorPoint = Vector2.new(0, 1),
			Position = UDim2.new(0.25, 0, 0.9, -14),
			Size = UDim2.new(0.25, 0, 0, labelsize + 4),
			BackgroundTransparency = 1,
			Font = Enum.Font.Arcade,
			Text = "LOADING",
			TextColor3 = CYAN,
			TextSize = labelsize,
			TextXAlignment = Enum.TextXAlignment.Left,
			ZIndex = 43,
		})
		local barpct = new("TextLabel", scene, {
			AnchorPoint = Vector2.new(1, 1),
			Position = UDim2.new(0.75, 0, 0.9, -14),
			Size = UDim2.new(0.25, 0, 0, labelsize + 4),
			BackgroundTransparency = 1,
			Font = Enum.Font.Arcade,
			Text = "000%",
			TextColor3 = MAGENTA,
			TextSize = labelsize,
			TextXAlignment = Enum.TextXAlignment.Right,
			ZIndex = 43,
		})
		new("TextLabel", scene, {
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.new(0.5, 0, 0.965, 0),
			Size = UDim2.new(0.6, 0, 0, 18),
			BackgroundTransparency = 1,
			Font = Enum.Font.Arcade,
			Text = "UHHHHHH SOFT (C) 198X   -   V" .. UhhhhhhVersion,
			TextColor3 = WHITE,
			TextTransparency = 0.5,
			TextSize = math.clamp(math.floor(H / 70), 10, 16),
			ZIndex = 43,
		})
		new("TextLabel", scene, {
			AnchorPoint = Vector2.new(1, 0.5),
			Position = UDim2.new(0.985, 0, 0.965, 0),
			Size = UDim2.new(0.2, 0, 0, 18),
			BackgroundTransparency = 1,
			Font = Enum.Font.Arcade,
			Text = "CLICK TO SKIP",
			TextColor3 = WHITE,
			TextTransparency = 0.65,
			TextSize = math.clamp(math.floor(H / 80), 9, 14),
			TextXAlignment = Enum.TextXAlignment.Right,
			ZIndex = 43,
		})

		-- CRT overlay: scanlines, tracking band, vignette, final white-out
		local overlay = new("Frame", root, {
			Size = UDim2.new(1, 0, 1, 0),
			BackgroundTransparency = 1,
			BorderSizePixel = 0,
			ZIndex = 100,
		})
		local step = math.max(4, math.ceil(H / 200))
		for y = 0, H, step do
			new("Frame", overlay, {
				Position = UDim2.fromOffset(0, y),
				Size = UDim2.new(1, 0, 0, 1),
				BackgroundColor3 = BLACK,
				BackgroundTransparency = 0.8,
				BorderSizePixel = 0,
				ZIndex = 101,
			})
		end
		local band = new("Frame", overlay, {
			Size = UDim2.new(1, 0, 0.07, 0),
			BackgroundColor3 = WHITE,
			BorderSizePixel = 0,
			ZIndex = 102,
		})
		new("UIGradient", band, {
			Rotation = 90,
			Transparency = NumberSequence.new({
				NumberSequenceKeypoint.new(0, 1),
				NumberSequenceKeypoint.new(0.5, 0.88),
				NumberSequenceKeypoint.new(1, 1),
			}),
		})
		local function edge(pos, size, rot)
			local e = new("Frame", overlay, {
				Position = pos,
				Size = size,
				BackgroundColor3 = BLACK,
				BorderSizePixel = 0,
				ZIndex = 103,
			})
			new("UIGradient", e, {Rotation = rot, Transparency = NumberSequence.new(0.2, 1)})
		end
		edge(UDim2.new(0, 0, 0, 0), UDim2.new(1, 0, 0.2, 0), 90)
		edge(UDim2.new(0, 0, 0.8, 0), UDim2.new(1, 0, 0.2, 0), 270)
		edge(UDim2.new(0, 0, 0, 0), UDim2.new(0.14, 0, 1, 0), 0)
		edge(UDim2.new(0.86, 0, 0, 0), UDim2.new(0.14, 0, 1, 0), 180)
		local whiteout = new("Frame", root, {
			Size = UDim2.new(1, 0, 1, 0),
			BackgroundColor3 = WHITE,
			BackgroundTransparency = 1,
			BorderSizePixel = 0,
			ZIndex = 200,
		})

		while true do
			RunService.Heartbeat:Wait()
			local t = os.clock() - MusicPlayer.IntroStart
			local st = t - BOOT_EXTRA
			if t >= T_END or skip then break end
			if NyanDelayedPlay and not NyanPlayed and t >= 2.25 + BOOT_EXTRA then
				NyanPlayed = true
				IntroSound.TimePosition = 0
				IntroSound:Play()
			end
			local scr2 = Util.GetScreenSize()
			W, H = scr2.X, scr2.Y

			-- CRT turning on
			if t < 0.25 then
				crt.Size = UDim2.new(t / 0.25, 0, 0, 3)
			elseif t < 0.6 then
				local a = (t - 0.25) / 0.35
				crt.Size = UDim2.new(1, 0, a, math.floor(3 * (1 - a)))
				crt.BackgroundTransparency = a * a
			else
				crt.Visible = false
			end

			-- boot text, then the scene flickers on like an old TV
			if t < BIOS_END then
				-- stage 1: BIOS POST
				boot.Text = typedlines(bioslines, t, 90)
				boot.Visible = true
				boot2.Visible = false
				biosfoot.Visible = t > 1.85
			elseif t < BOOT_START then
				-- the screen blanks for a moment between BIOS and boot manager
				boot.Visible = false
				boot2.Visible = false
				biosfoot.Visible = false
			elseif t < 2.25 + BOOT_EXTRA then
				-- stage 2: boot manager
				boot2.Text = typedlines(bootlines, t, 60)
				boot2.Visible = true
				boot.Visible = false
				biosfoot.Visible = false
			else
				boot.Visible = false
				boot2.Visible = false
				biosfoot.Visible = false
			end
			if t < 1.95 + BOOT_EXTRA then
				scene.Visible = false
			elseif t < 2.25 + BOOT_EXTRA then
				scene.Visible = rng:NextNumber() > 0.45
			else
				scene.Visible = true
			end

			if sceneimg then
				-- video frames, starting when the scene shows up
				local fi = math.clamp(math.floor((t - (2.25 + BOOT_EXTRA)) * SCENE_FPS) + 1, 1, #SceneFrames)
				if fi ~= lastframe then
					lastframe = fi
					sceneimg.Image = SceneFrames[fi]
				end
			else
				local nf = math.floor(t * NYAN_FPS)
				local ni = nf % 12 + 1
				-- stars: stepped scroll to the left + twinkle
				local twinkle = math.floor(nf / 2)
				for _, s in nyanstars do
					local steps = s.big and STAR_STEPS_BIG or STAR_STEPS_SMALL
					local k = steps[(twinkle + s.ph) % #steps + 1]
					if k < 0 then
						s.f.Visible = false
						s.v.Visible = false
					else
						local sx = ((s.gx - nf) % GRID_W) * P - 4 * P + P / 2
						local sy = s.gy * P + P / 2
						local len = (k * 2 + 1) * P
						s.f.Visible = true
						s.f.Position = UDim2.fromOffset(sx, sy)
						s.f.Size = UDim2.fromOffset(len, P)
						s.v.Position = UDim2.fromOffset(sx, sy)
						s.v.Size = UDim2.fromOffset(P, len)
						s.v.Visible = k > 0
					end
				end

				-- the cat: 12 frame cycle (body bob, tail, legs) + the stepped rainbow behind it
				local catx = math.floor((W * 0.52 - CAT_W * P * 0.5) / P) * P
				local caty = math.floor((H * 0.58 - CAT_H * P * 0.5) / P) * P
				cat.Position = UDim2.fromOffset(catx, caty)
				local trailtop = caty + (BODY_Y0 + RB_TOP) * P
				if #catimages > 0 then
					trailtop = caty + CAT_H * P * IMAGE_TRAIL_TOP
					local cur = math.floor(t * IMAGE_FPS) % #catimages + 1
					for i, img in ipairs(catimages) do
						img.Visible = (i == cur)
					end
				elseif bodyholder then
					bodyholder.Position = UDim2.fromOffset(0, (BODY_Y0 - NYAN_BODY_DY[ni]) * P)
					for name, h in tails do
						h.Visible = (name == NYAN_TAIL[ni])
					end
					local lp = NYAN_LEGPOSE[ni]
					for i, leg in ipairs(legs) do
						local def = NYAN_LEGSET[i]
						local dx = def.back and lp[1] or lp[2]
						leg.Position = UDim2.fromOffset((def.x + dx) * P, (def.y + BODY_Y0 - lp[3]) * P)
					end
				end
				local rbright = catx + RB_END_X * P
				local rbphase = NYAN_RB_PHASE[ni]
				for j, col in ipairs(trail) do
					local cx = rbright - j * trailcw
					if cx + trailcw > 0 then
						col.Position = UDim2.fromOffset(cx, trailtop + (((j + rbphase) % 2 == 0) and -P or 0))
						col.Visible = true
					else
						col.Visible = false
					end
				end
			end

			-- title with glitch bursts
			local gs = 0
			for _, g in glitchtimes do
				if st >= g and st < g + 0.14 then
					gs = 1
				end
			end
			local dx = 2 + gs * rng:NextInteger(6, 18)
			local jx = gs * rng:NextInteger(-14, 14)
			local jy = gs * rng:NextInteger(-5, 5)
			local tw, th = W * 0.8, H * 0.17
			local tx, ty = W * 0.5 + jx, H * 0.2 + jy
			local n1 = math.floor(math.max(0, st - 3.1) * 12)
			place(tShadow, tx + 5, ty + 5, tw, th, n1)
			place(tMag, tx + dx, ty, tw, th, n1)
			place(tCyan, tx - dx, ty, tw, th, n1)
			place(tMain, tx, ty, tw, th, n1)
			local n2 = math.floor(math.max(0, st - 3.8) * 16)
			local hue = (st * 0.35) % 1
			setrainbow(gMain, hue)
			setrainbow(gMag, hue + 0.33)
			setrainbow(gCyan, hue + 0.66)
			place(sShadow, W * 0.5 + 3, H * 0.31 + 3, W * 0.8, H * 0.07, n2)
			place(sMain, W * 0.5 + jx * 0.5, H * 0.31, W * 0.8, H * 0.07, n2)
			glitchbar.Visible = gs > 0
			if gs > 0 then
				glitchbar.Position = UDim2.fromOffset(0, rng:NextInteger(0, math.floor(H)))
				glitchbar.Size = UDim2.new(1, 0, 0, rng:NextInteger(3, 26))
			end

			-- loading bar
			local p = math.clamp((st - 2.4) / (3.3 + NyanHold), 0, 1)
			local stepped = math.floor(p * 20) / 20
			barfill.Size = UDim2.new(stepped, 0, 1, 0)
			barpct.Text = string.format("%03d%%", math.floor(stepped * 100))
			if p < 1 then
				barlabel.Text = "LOADING" .. string.rep(".", math.floor(t * 3) % 4)
			else
				barlabel.Text = math.floor(t * 6) % 2 == 0 and "SYSTEM READY" or ""
			end

			-- CRT overlay
			band.Position = UDim2.new(0, 0, (t * 0.5) % 1.4 - 0.2, 0)
			whiteout.BackgroundTransparency = 1 - math.clamp((t - (T_END - 0.3)) / 0.3, 0, 1)
		end
	end
	local introok, introerr = pcall(RunRetroIntro)
	if not introok then
		warn("[intro] " .. tostring(introerr))
	end
	if IntroConn then
		IntroConn:Disconnect()
	end
	local flash = Util.Instance("Frame", UIMainFrame)
	flash.AnchorPoint = Vector2.new(0, 0)
	flash.Position = UDim2.new(0, 0, 0, 0)
	flash.Size = UDim2.new(1, 0, 1, 0)
	flash.BackgroundColor3 = Color3.new(1, 1, 1)
	flash.BackgroundTransparency = 0
	flash.BorderSizePixel = 0
	flash.Interactable = false
	flash.ZIndex = 256
	if IntroRoot then
		IntroRoot:Destroy()
	end
	UIMainFrame.BackgroundTransparency = 1
	TweenService:Create(flash, TweenInfo.new(1), {
		BackgroundTransparency = 1
	}):Play()
	Debris:AddItem(flash, 1)
	-- intro over: crossfade from the intro track into the normal UI music
	if MusicPlayer.IntroHasMusic then
		TweenService:Create(IntroSound, TweenInfo.new(1, Enum.EasingStyle.Linear), {
			Volume = 0
		}):Play()
		Debris:AddItem(IntroSound, 1.2)
		task.spawn(function()
			MusicPlayer.PlayMusic()
			if not SaveData.MuteUIMusic then
				TweenService:Create(UISound.Music, TweenInfo.new(1, Enum.EasingStyle.Linear), {
					Volume = 1
				}):Play()
			end
		end)
	end
end

SaveData.MuteUIMusic = not not SaveData.MuteUIMusic
SaveData.MuteReanimMusic = not not SaveData.MuteReanimMusic
SaveData.MuteUISound = not not SaveData.MuteUISound

if SaveData.MuteUIMusic then
	if SaveData.SkipIntro then
		UISound.Music.Volume = 0
	else
		TweenService:Create(UISound.Music, TweenInfo.new(3, Enum.EasingStyle.Linear), {
			Volume = 0
		}):Play()
	end
end

UISound.Click = Util.Instance("Sound", UIMainFrame)
